    static func surfaceFeatureDetail(_ feature: SurfaceFeature) -> String {
        switch feature {
        case .statusFirst:
            return pick([.korean: "휴가를 잡아 두셨네요. 이제 앱을 열면 남은 연차와 다가오는 휴가부터 보여 드려요. 달력은 캘린더 탭에 그대로 있어요.", .english: "You’ve planned some leave. From now on the app opens with your remaining days and upcoming leave. The calendar is still in the Calendar tab.", .japanese: "休暇の予定が入りました。これからはアプリを開くと、残りの年休と近づく休暇から表示します。カレンダーはカレンダータブにそのままあります。", .chinese: "你已经安排了假期。之后打开应用时，会先显示剩余年假和即将到来的假期。日历仍在“日历”标签中。", .german: "Du hast Urlaub eingeplant. Ab jetzt zeigt die App beim Öffnen zuerst deine Resttage und den nächsten Urlaub. Der Kalender bleibt im Tab „Kalender“.", .french: "Vous avez prévu des congés. Désormais, l’app s’ouvre sur vos jours restants et vos prochains congés. Le calendrier reste dans l’onglet Calendrier.", .spanish: "Ya tienes días planificados. A partir de ahora, la app se abre con tus días restantes y tus próximas ausencias. El calendario sigue en la pestaña Calendario.", .italian: "Hai pianificato delle ferie. D’ora in poi l’app si apre con i giorni rimasti e le prossime ferie. Il calendario resta nella scheda Calendario.", .portuguese: "Você já planejou uma folga. Agora o app abre mostrando os dias restantes e as próximas folgas. O calendário continua na aba Calendário.", .chineseTraditional: "你已經安排了假期。之後打開 App 時，會先顯示剩餘特休和即將到來的假期。行事曆仍在「行事曆」分頁中。", .dutch: "Je hebt verlof gepland. Voortaan opent de app met je resterende dagen en je volgende verlof. De kalender staat nog steeds onder Agenda.", .swedish: "Du har planerat ledighet. Nu öppnas appen med dina återstående dagar och din nästa ledighet. Kalendern finns kvar under Kalender.", .norwegian: "Du har planlagt fri. Nå åpnes appen med dagene du har igjen og neste fri. Kalenderen ligger fortsatt under Kalender.", .danish: "Du har planlagt fri. Nu åbner appen med dine resterende dage og din næste fri. Kalenderen ligger stadig under Kalender.", .finnish: "Olet suunnitellut lomaa. Nyt sovellus avautuu jäljellä oleviin päiviin ja seuraavaan lomaan. Kalenteri löytyy edelleen Kalenteri-välilehdeltä.", .polish: "Masz już zaplanowany urlop. Teraz aplikacja otwiera się na pozostałych dniach i najbliższym urlopie. Kalendarz nadal jest w karcie Kalendarz.", .czech: "Máte naplánovanou dovolenou. Aplikace se teď otevře na zbývajících dnech a nejbližší dovolené. Kalendář najdete dál na kartě Kalendář.", .greek: "Έχετε προγραμματίσει άδεια. Από τώρα η εφαρμογή ανοίγει με τις υπόλοιπες μέρες και την επόμενη άδειά σας. Το ημερολόγιο παραμένει στην καρτέλα Ημερολόγιο.", .turkish: "İzin planladınız. Artık uygulama kalan günlerinizi ve yaklaşan izninizi göstererek açılıyor. Takvim, Takvim sekmesinde duruyor.", .russian: "Вы запланировали отпуск. Теперь приложение сначала показывает оставшиеся дни и ближайший отпуск. Календарь по-прежнему во вкладке «Календарь».", .indonesian: "Anda sudah merencanakan cuti. Mulai sekarang aplikasi dibuka dengan sisa cuti dan cuti terdekat. Kalender tetap ada di tab Kalender.", .thai: "คุณวางแผนวันลาไว้แล้ว จากนี้แอปจะเปิดด้วยวันลาที่เหลือและวันลาที่ใกล้จะถึงก่อน ปฏิทินยังอยู่ในแท็บปฏิทินเหมือนเดิม", .vietnamese: "Bạn đã lên lịch nghỉ. Từ giờ ứng dụng sẽ mở với số ngày phép còn lại và kỳ nghỉ sắp tới. Lịch vẫn nằm ở thẻ Lịch."])
        case .photoImport:
            return pick([.korean: "기록이 늘면 하나씩 넣기가 번거로워져요. 회사 휴가 내역을 찍으면 날짜와 종류를 읽어 넣어 줘요. 위 카드의 사진 버튼을 눌러 보세요.", .english: "Adding leave one by one gets tedious. Take a photo of your company’s leave records and the dates and types are filled in. Try the photo button on the card above.", .japanese: "記録が増えると1件ずつの入力は手間です。会社の休暇履歴を撮影すると、日付と種類を読み取って登録します。上のカードの写真ボタンをどうぞ。", .chinese: "记录多了，逐条添加会很麻烦。拍下公司的休假记录，就能自动读取日期和类型。试试上方卡片的照片按钮。", .german: "Einzeln eintragen wird schnell mühsam. Fotografiere deine Urlaubsübersicht der Firma, und Daten und Art werden übernommen. Probiere die Foto-Taste auf der Karte oben aus.", .french: "Tout saisir un par un devient vite pénible. Photographiez votre relevé de congés : les dates et les types sont repris. Essayez le bouton photo de la carte ci-dessus.", .spanish: "Añadirlas una a una acaba cansando. Fotografía tu registro de ausencias de la empresa y se leen las fechas y los tipos. Prueba el botón de foto de la tarjeta de arriba.", .italian: "Inserirli uno a uno diventa scomodo. Fotografa il riepilogo aziendale dei permessi e date e tipi vengono letti da soli. Prova il pulsante foto nella scheda qui sopra.", .portuguese: "Adicionar uma a uma cansa. Fotografe o registro de folgas da empresa e as datas e os tipos são lidos para você. Experimente o botão de foto no cartão acima.", .chineseTraditional: "記錄多了，逐筆新增會很麻煩。拍下公司的休假紀錄，就能自動讀取日期和類型。試試上方卡片的照片按鈕。", .dutch: "Eén voor één invoeren wordt al snel lastig. Maak een foto van je verlofoverzicht en de datums en types worden ingevuld. Probeer de fotoknop op de kaart hierboven.", .swedish: "Att lägga till en i taget blir snabbt krångligt. Fotografera företagets ledighetslista så läses datum och typ in. Prova fotoknappen på kortet ovan.", .norwegian: "Å legge inn én og én blir fort tungvint. Ta bilde av feriooversikten fra jobben, så leses datoer og typer inn. Prøv bildeknappen på kortet over.", .danish: "Det bliver hurtigt besværligt at tilføje én ad gangen. Tag et foto af firmaets ferieoversigt, så aflæses datoer og typer. Prøv fotoknappen på kortet ovenfor.", .finnish: "Yksi kerrallaan lisääminen käy työlääksi. Kuvaa työpaikan lomatiedot, niin päivät ja tyypit luetaan automaattisesti. Kokeile yllä olevan kortin kuvapainiketta.", .polish: "Dodawanie po jednym szybko staje się uciążliwe. Zrób zdjęcie firmowego zestawienia urlopów, a daty i rodzaje zostaną odczytane. Wypróbuj przycisk zdjęcia na karcie powyżej.", .czech: "Přidávat po jednom je brzy otravné. Vyfoť firemní přehled volna a data i typy se načtou samy. Zkus tlačítko fotky na kartě výše.", .greek: "Η καταχώριση μία μία γίνεται κουραστική. Φωτογράφισε το αρχείο αδειών της εταιρείας και οι ημερομηνίες και οι τύποι διαβάζονται αυτόματα. Δοκίμασε το κουμπί φωτογραφίας στην παραπάνω κάρτα.", .turkish: "Tek tek eklemek zamanla yorar. Şirketin izin kayıtlarının fotoğrafını çek, tarih ve türler otomatik okunsun. Yukarıdaki karttaki fotoğraf düğmesini dene.", .russian: "Вносить по одному со временем утомляет. Сфотографируйте сведения об отпусках с работы, и даты и виды считаются сами. Попробуйте кнопку фото на карточке выше.", .indonesian: "Menambah satu per satu lama-lama merepotkan. Foto catatan cuti kantormu, lalu tanggal dan jenisnya terbaca otomatis. Coba tombol foto di kartu atas.", .thai: "การเพิ่มทีละรายการเริ่มยุ่งยาก ถ่ายรูปประวัติการลาของบริษัทแล้วระบบจะอ่านวันที่และประเภทให้ ลองแตะปุ่มรูปภาพบนการ์ดด้านบน", .vietnamese: "Thêm từng mục một sẽ nhanh chóng thấy phiền. Chụp bảng nghỉ phép của công ty để tự đọc ngày và loại. Hãy thử nút ảnh trên thẻ phía trên."])
        case .sharePlan:
            return pick([.korean: "잡아 둔 휴가를 가족이나 동료에게 알려야 할 때 써요. 내 현황과 일정을 그림 한 장으로 보낼 수 있어요. 위 카드의 공유 버튼을 눌러 보세요.", .english: "For when family or coworkers need to know about your upcoming leave. Send your balance and dates as a single image. Try the share button on the card above.", .japanese: "予定した休暇を家族や同僚に伝えるときに使います。残日数と予定を1枚の画像で送れます。上のカードの共有ボタンをどうぞ。", .chinese: "需要把假期告诉家人或同事时可以用。把余额和日程做成一张图发送。试试上方卡片的分享按钮。", .german: "Für den Moment, in dem Familie oder Kollegen von deinem Urlaub erfahren sollen. Sende Resttage und Termine als ein Bild. Probiere die Teilen-Taste auf der Karte oben aus.", .french: "Pratique pour prévenir vos proches ou collègues de vos congés à venir. Envoyez votre solde et vos dates en une image. Essayez le bouton de partage de la carte ci-dessus.", .spanish: "Para cuando tu familia o tus compañeros deban saber de tus próximas ausencias. Envía tu saldo y tus fechas en una imagen. Prueba el botón de compartir de la tarjeta de arriba.", .italian: "Serve quando famiglia o colleghi devono sapere dei tuoi prossimi permessi. Invia saldo e date in un’unica immagine. Prova il pulsante di condivisione nella scheda qui sopra.", .portuguese: "Para quando a família ou os colegas precisam saber das suas próximas folgas. Envie saldo e datas em uma imagem. Experimente o botão de compartilhar no cartão acima.", .chineseTraditional: "需要把假期告訴家人或同事時可以用。把餘額和行程做成一張圖傳送。試試上方卡片的分享按鈕。", .dutch: "Voor als familie of collega’s van je verlof moeten weten. Stuur je saldo en datums als één afbeelding. Probeer de deelknop op de kaart hierboven.", .swedish: "För när familj eller kollegor behöver veta om din ledighet. Skicka saldo och datum som en enda bild. Prova delningsknappen på kortet ovan.", .norwegian: "Til når familie eller kolleger må vite om ferien din. Send saldo og datoer som ett bilde. Prøv delingsknappen på kortet over.", .danish: "Til når familie eller kolleger skal kende din ferie. Send saldo og datoer som ét billede. Prøv delingsknappen på kortet ovenfor.", .finnish: "Kun perheen tai työkavereiden pitää tietää tulevista lomistasi. Lähetä saldo ja päivät yhtenä kuvana. Kokeile yllä olevan kortin jakopainiketta.", .polish: "Gdy rodzina lub współpracownicy muszą wiedzieć o Twoim urlopie. Wyślij saldo i daty jako jeden obraz. Wypróbuj przycisk udostępniania na karcie powyżej.", .czech: "Až o tvém volnu potřebuje vědět rodina nebo kolegové. Pošli zůstatek a data jako jeden obrázek. Zkus tlačítko sdílení na kartě výše.", .greek: "Για όταν η οικογένεια ή οι συνάδελφοι πρέπει να μάθουν για την άδειά σου. Στείλε υπόλοιπο και ημερομηνίες σε μία εικόνα. Δοκίμασε το κουμπί κοινοποίησης στην παραπάνω κάρτα.", .turkish: "Ailen veya iş arkadaşların iznini bilmesi gerektiğinde kullan. Bakiyeni ve tarihlerini tek görselle gönder. Yukarıdaki karttaki paylaş düğmesini dene.", .russian: "Когда семье или коллегам нужно знать о вашем отпуске. Отправьте остаток и даты одной картинкой. Попробуйте кнопку «Поделиться» на карточке выше.", .indonesian: "Saat keluarga atau rekan kerja perlu tahu cutimu. Kirim sisa cuti dan tanggalnya dalam satu gambar. Coba tombol bagikan di kartu atas.", .thai: "ใช้เมื่อต้องแจ้งวันลาให้ครอบครัวหรือเพื่อนร่วมงานทราบ ส่งยอดคงเหลือและวันที่เป็นภาพเดียวได้ ลองแตะปุ่มแชร์บนการ์ดด้านบน", .vietnamese: "Dùng khi cần báo lịch nghỉ cho gia đình hoặc đồng nghiệp. Gửi số ngày còn lại và lịch nghỉ trong một ảnh. Hãy thử nút chia sẻ trên thẻ phía trên."])
        case .restPace:
            return pick([.korean: "기록이 쌓여 쉬는 흐름이 보이기 시작했어요. 올해 얼마나 쉬었는지와 마지막 휴식을 보여 줘서, 너무 오래 쉬지 않았는지 알 수 있어요. 현황 화면에 추가했어요.", .english: "You now have enough records to see how you rest. It shows this year’s pace and your last break, so you can tell if you’ve gone too long without one. It’s now on the Home screen.", .japanese: "記録が増えて、休み方の流れが見えてきました。今年のペースと前回の休みから、休まず働きすぎていないか分かります。ホームに追加しました。", .chinese: "记录多了，休息规律也能看出来了。它显示今年的节奏和上次休息，让你知道是否太久没休息。已添加到首页。", .german: "Jetzt sieht man, wie du dich erholst. Tempo und letzte Pause zeigen dir, ob du zu lange keine Auszeit hattest. Du findest es jetzt auf dem Startbildschirm.", .french: "Vos congés montrent désormais votre rythme de repos. Il indique votre rythme annuel et votre dernière pause, pour voir si elle date trop. C’est maintenant sur l’accueil.", .spanish: "Ya se ve cómo descansas. Muestra tu ritmo del año y tu último descanso, para saber si llevas demasiado sin parar. Ya está en Inicio.", .italian: "Ora si vede come riposi. Mostra il ritmo dell’anno e l’ultima pausa, così capisci se è passato troppo tempo. Lo trovi nella schermata principale.", .portuguese: "Agora já dá para ver como você descansa. Mostra o ritmo do ano e a última pausa, para saber se faz tempo demais. Já está na tela inicial.", .chineseTraditional: "記錄多了，休息規律也看得出來了。它顯示今年的節奏和上次休息，讓你知道是否太久沒休息。已加到首頁。", .dutch: "Nu is te zien hoe je rust neemt. Het toont je tempo en je laatste pauze, zodat je ziet of die te lang geleden is. Je vindt het nu op het beginscherm.", .swedish: "Nu syns det hur du vilar. Det visar årets takt och senaste pausen, så att du ser om det gått för lång tid. Det finns nu på startskärmen.", .norwegian: "Nå ser du hvordan du tar pauser. Det viser årets tempo og siste pause, så du ser om det er for lenge siden. Det ligger nå på startskjermen.", .danish: "Nu kan du se, hvordan du holder fri. Det viser årets tempo og din seneste pause, så du kan se, om det er for længe siden. Det ligger nu på startskærmen.", .finnish: "Nyt levon rytmi alkaa näkyä. Se kertoo vuoden tahdin ja viime tauon, joten näet, onko edellisestä liian kauan. Löydät sen nyt aloitusnäkymästä.", .polish: "Teraz widać, jak odpoczywasz. Pokazuje tempo roku i ostatnią przerwę, więc wiesz, czy nie minęło zbyt dużo czasu. Jest już na ekranie głównym.", .czech: "Teď je vidět, jak odpočíváš. Ukazuje tempo roku a poslední pauzu, takže poznáš, jestli to není moc dlouho. Najdeš to na hlavní obrazovce.", .greek: "Τώρα φαίνεται πώς ξεκουράζεσαι. Δείχνει τον ρυθμό της χρονιάς και το τελευταίο διάλειμμα, για να ξέρεις αν πέρασε πολύς καιρός. Θα το βρεις στην αρχική οθόνη.", .turkish: "Artık nasıl dinlendiğin görünüyor. Yılın temposunu ve son molanı gösterir; çok uzun süredir mola vermediğini anlarsın. Ana ekrana eklendi.", .russian: "Теперь видно, как вы отдыхаете. Показаны темп года и последний перерыв, чтобы понять, не слишком ли давно он был. Это уже на главном экране.", .indonesian: "Kini terlihat cara kamu beristirahat. Menampilkan ritme tahun ini dan istirahat terakhir, agar tahu jika sudah terlalu lama. Kini ada di layar utama.", .thai: "ตอนนี้เห็นจังหวะการพักของคุณแล้ว แสดงจังหวะของปีและการพักครั้งล่าสุด จึงรู้ว่าไม่ได้พักมานานเกินไปหรือไม่ เพิ่มไว้ที่หน้าหลักแล้ว", .vietnamese: "Giờ đã thấy được nhịp nghỉ của bạn. Thẻ cho biết nhịp của năm và lần nghỉ gần nhất, để biết bạn đã làm việc quá lâu chưa. Đã thêm vào màn hình chính."])
        case .leaveKinds:
            return pick([.korean: "연차 말고 다른 휴가도 쓰고 계시네요. 회사에서 부르는 이름으로 종류를 만들면 따로 세고 한도도 볼 수 있어요. 휴가 등록 화면에서 더할 수 있어요.", .english: "You use more than regular leave. Create types named the way your company does, then count them separately and track allowances. Add them when registering leave.", .japanese: "年休以外の休暇も使っていますね。会社での呼び名で種類を作ると、別々に数えて上限も確認できます。休暇の登録画面で追加できます。", .chinese: "你也在用年假以外的假期。按公司叫法创建类型，就能分开统计并查看额度。可在登记假期时添加。", .german: "Du nutzt nicht nur normalen Urlaub. Lege Arten mit den Namen deiner Firma an, zähle sie getrennt und behalte Kontingente im Blick. Das geht beim Eintragen von Urlaub.", .french: "Vous utilisez d’autres congés que les congés payés. Créez des types au nom utilisé par votre entreprise pour les compter à part et suivre les quotas. Ajoutez-les en enregistrant un congé.", .spanish: "Usas más que las vacaciones normales. Crea tipos con el nombre de tu empresa para contarlos aparte y ver sus cupos. Puedes añadirlos al registrar una ausencia.", .italian: "Non usi solo le ferie. Crea i tipi con i nomi della tua azienda per contarli a parte e controllare il monte annuo. Puoi aggiungerli quando registri un permesso.", .portuguese: "Você usa mais do que as férias normais. Crie tipos com os nomes da sua empresa para contar à parte e ver as cotas. Adicione ao registrar uma folga.", .chineseTraditional: "你也在用特休以外的假期。依公司的叫法建立類型，就能分開統計並查看額度。可在登記假期時新增。", .dutch: "Je gebruikt meer dan gewoon verlof. Maak types met de namen van je bedrijf, tel ze apart en houd je tegoed bij. Dat kan bij het invoeren van verlof.", .swedish: "Du använder mer än vanlig semester. Skapa typer med företagets namn, räkna dem separat och följ kvoter. Lägg till dem när du registrerar ledighet.", .norwegian: "Du bruker mer enn vanlig ferie. Lag typer med navnene jobben bruker, tell dem hver for seg og følg kvotene. Legg dem til når du registrerer fravær.", .danish: "Du bruger mere end almindelig ferie. Opret typer med firmaets navne, tæl dem hver for sig og følg kvoterne. Tilføj dem, når du registrerer fravær.", .finnish: "Käytät muutakin kuin vuosilomaa. Luo tyypit työpaikkasi nimillä, laske ne erikseen ja seuraa kiintiöitä. Lisää ne, kun kirjaat loman.", .polish: "Korzystasz nie tylko ze zwykłego urlopu. Twórz rodzaje pod firmowymi nazwami, licz je osobno i śledź limity. Dodasz je przy zapisywaniu urlopu.", .czech: "Nepoužíváš jen běžnou dovolenou. Vytvoř typy s firemními názvy, počítej je zvlášť a sleduj nároky. Přidáš je při zápisu volna.", .greek: "Δεν χρησιμοποιείς μόνο κανονική άδεια. Δημιούργησε τύπους με τα ονόματα της εταιρείας, μέτρησέ τους χωριστά και δες τα όρια. Προσθέτονται κατά την καταχώριση άδειας.", .turkish: "Yalnızca yıllık izin kullanmıyorsun. Şirketindeki adlarla türler oluştur, ayrı say ve haklarını izle. İzin kaydederken ekleyebilirsin.", .russian: "Вы пользуетесь не только обычным отпуском. Создайте виды с названиями, принятыми на работе, считайте их отдельно и следите за лимитами. Добавить можно при записи отпуска.", .indonesian: "Kamu memakai lebih dari cuti biasa. Buat jenis dengan nama dari kantormu, hitung terpisah, dan pantau jatahnya. Tambahkan saat mencatat cuti.", .thai: "คุณใช้วันลาอื่นนอกจากพักร้อนด้วย สร้างประเภทตามชื่อที่บริษัทใช้ เพื่อนับแยกและดูโควตาได้ เพิ่มได้ตอนบันทึกวันลา", .vietnamese: "Bạn dùng cả các loại nghỉ khác ngoài phép năm. Tạo loại theo tên công ty để tính riêng và theo dõi hạn mức. Có thể thêm khi ghi ngày nghỉ."])
        case .longView:
            return pick([.korean: "앞으로 잡아 둔 휴가가 여러 번이면 한 달씩 넘겨 보기 번거로워요. 달력 위에서 여러 달을 한눈에 볼 수 있어요.", .english: "With several leaves coming up, flipping month by month gets slow. You can now see several months at once at the top of the Calendar.", .japanese: "予定した休暇が複数あると、1か月ずつめくるのは手間です。カレンダーの上で複数の月をひと目で見られます。", .chinese: "安排了多次假期后，逐月翻看很麻烦。现在可在日历顶部一次查看多个月。", .german: "Bei mehreren geplanten Urlauben wird das Blättern mühsam. Oben im Kalender siehst du jetzt mehrere Monate auf einmal.", .french: "Avec plusieurs congés à venir, feuilleter mois par mois devient long. En haut du calendrier, voyez désormais plusieurs mois d’un coup.", .spanish: "Con varias ausencias por delante, pasar mes a mes es lento. Arriba en el calendario ya puedes ver varios meses a la vez.", .italian: "Con più permessi in arrivo, sfogliare mese per mese è lento. In cima al calendario ora puoi vedere più mesi insieme.", .portuguese: "Com várias folgas pela frente, passar mês a mês é demorado. No topo do calendário, agora você vê vários meses de uma vez.", .chineseTraditional: "安排了多次假期後，逐月翻看很麻煩。現在可在月曆頂端一次檢視多個月。", .dutch: "Met meerdere verlofperiodes in het vooruitzicht is per maand bladeren traag. Bovenaan de kalender zie je nu meerdere maanden tegelijk.", .swedish: "Med flera ledigheter framför dig tar det tid att bläddra månad för månad. Högst upp i kalendern ser du nu flera månader samtidigt.", .norwegian: "Med flere ferier foran deg tar det tid å bla måned for måned. Øverst i kalenderen ser du nå flere måneder samtidig.", .danish: "Med flere ferier forude tager det tid at bladre måned for måned. Øverst i kalenderen kan du nu se flere måneder ad gangen.", .finnish: "Kun lomia on tulossa useita, kuukausittain selaaminen on hidasta. Kalenterin yläosassa näet nyt monta kuukautta kerralla.", .polish: "Przy kilku zaplanowanych urlopach przeglądanie miesiąc po miesiącu trwa długo. U góry kalendarza zobaczysz teraz kilka miesięcy naraz.", .czech: "S více plánovanými volny je listování po měsících pomalé. Nahoře v kalendáři teď uvidíš víc měsíců najednou.", .greek: "Με πολλές άδειες μπροστά σου, η εναλλαγή μήνα μήνα είναι αργή. Στο πάνω μέρος του ημερολογίου βλέπεις τώρα πολλούς μήνες μαζί.", .turkish: "Birkaç iznin yaklaşırken ay ay gezinmek yavaşlar. Takvimin üstünden artık birkaç ayı birden görebilirsin.", .russian: "Когда впереди несколько отпусков, листать по месяцу долго. Вверху календаря теперь можно видеть сразу несколько месяцев.", .indonesian: "Dengan beberapa cuti ke depan, membuka per bulan jadi lambat. Di atas kalender kini kamu bisa melihat beberapa bulan sekaligus.", .thai: "เมื่อมีวันลาหลายครั้ง การเปิดทีละเดือนจะช้า ตอนนี้ดูหลายเดือนพร้อมกันได้ที่ด้านบนของปฏิทิน", .vietnamese: "Khi có nhiều kỳ nghỉ sắp tới, lật từng tháng rất chậm. Giờ bạn có thể xem nhiều tháng cùng lúc ở đầu lịch."])
        case .everything:
            return pick([.korean: "기본은 이제 다 익히셨어요. 쓰다 보면 보너스 연차, 가족 기념일, 캘린더 연결이 필요해질 수 있어요. 나머지 기능은 모두 설정에 있어요.", .english: "You’ve got the basics. In time you may want bonus leave, family anniversaries or calendar sync. Everything else is now in Settings.", .japanese: "基本はもう身につきました。使ううちにボーナス休暇、家族の記念日、カレンダー連携が必要になるかもしれません。残りの機能はすべて設定にあります。", .chinese: "基础功能你已掌握。之后可能会用到奖励假、家庭纪念日或日历同步。其余功能都在设置中。", .german: "Die Grundlagen sitzen. Mit der Zeit brauchst du vielleicht Bonusurlaub, Familienjahrestage oder Kalenderabgleich. Alles Weitere findest du jetzt in den Einstellungen.", .french: "Vous maîtrisez l’essentiel. Avec le temps, les congés bonus, les anniversaires familiaux ou la synchronisation du calendrier peuvent servir. Tout le reste est dans Réglages.", .spanish: "Ya dominas lo básico. Con el tiempo quizá necesites días extra, aniversarios familiares o sincronizar el calendario. Todo lo demás está en Ajustes.", .italian: "Ora conosci le basi. Col tempo potrebbero servirti permessi bonus, ricorrenze di famiglia o la sincronizzazione del calendario. Tutto il resto è in Impostazioni.", .portuguese: "Você já domina o básico. Com o tempo, pode precisar de folgas bônus, datas da família ou sincronizar o calendário. Todo o resto está em Ajustes.", .chineseTraditional: "基本功能你已掌握。之後可能會用到獎勵假、家庭紀念日或行事曆同步。其餘功能都在設定中。", .dutch: "Je kent nu de basis. Later wil je misschien bonusverlof, familiedagen of kalendersynchronisatie. Al het andere staat nu in Instellingen.", .swedish: "Nu kan du grunderna. Med tiden kan du behöva bonusledighet, familjens årsdagar eller kalendersynk. Allt annat finns nu i Inställningar.", .norwegian: "Nå kan du det grunnleggende. Etter hvert kan du trenge bonusferie, familiens merkedager eller kalendersynk. Alt det andre ligger nå i Innstillinger.", .danish: "Nu kan du det grundlæggende. Med tiden kan du få brug for bonusferie, familiens mærkedage eller kalendersynk. Alt det andet ligger nu i Indstillinger.", .finnish: "Perusteet ovat nyt hallussa. Ajan myötä saatat tarvita bonuslomia, perheen merkkipäiviä tai kalenterin synkronointia. Kaikki muu on nyt asetuksissa.", .polish: "Znasz już podstawy. Z czasem mogą przydać się urlop dodatkowy, rocznice rodzinne lub synchronizacja kalendarza. Cała reszta jest teraz w Ustawieniach.", .czech: "Základy už znáš. Časem se může hodit bonusové volno, rodinná výročí nebo synchronizace kalendáře. Všechno ostatní je teď v Nastavení.", .greek: "Έμαθες τα βασικά. Με τον καιρό ίσως χρειαστείς άδειες μπόνους, οικογενειακές επετείους ή συγχρονισμό ημερολογίου. Όλα τα υπόλοιπα είναι τώρα στις Ρυθμίσεις.", .turkish: "Temelleri öğrendin. Zamanla bonus izin, aile yıldönümleri veya takvim eşitleme gerekebilir. Diğer her şey artık Ayarlar’da.", .russian: "Основы вы освоили. Со временем могут пригодиться бонусные дни, семейные даты или синхронизация календаря. Всё остальное теперь в настройках.", .indonesian: "Kamu sudah paham dasarnya. Nanti kamu mungkin perlu cuti bonus, hari peringatan keluarga, atau sinkronisasi kalender. Semua lainnya kini ada di Pengaturan.", .thai: "คุณคุ้นเคยกับพื้นฐานแล้ว ต่อไปอาจต้องใช้วันลาโบนัส วันสำคัญของครอบครัว หรือการซิงค์ปฏิทิน ฟีเจอร์ที่เหลือทั้งหมดอยู่ในการตั้งค่าแล้ว", .vietnamese: "Bạn đã nắm được phần cơ bản. Sau này có thể bạn sẽ cần ngày nghỉ thưởng, ngày kỷ niệm gia đình hoặc đồng bộ lịch. Mọi thứ còn lại đã có trong Cài đặt."])
        }
    }

